namespace AssetHub.Core.Entities;

/// <summary>
/// Base for every aggregate. Ids are business-friendly strings (e.g. "EMP-1042", "AST-LAP-00047")
/// generated by ISequenceService, matching the codes the frontend already displays and stores as
/// foreign keys — this avoids a mapping layer between internal numeric ids and the ids the UI shows.
/// </summary>
public abstract class BaseEntity
{
    public string Id { get; set; } = string.Empty;
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    public DateTime? UpdatedAt { get; set; }
}
